#!/usr/bin/env python3
"""Generate the offline, searchable symbol catalog from design/symbols.json."""

import json
from pathlib import Path


def main():
    root = Path(__file__).resolve().parents[1]
    symbols = json.loads((root / "design/symbols.json").read_text(encoding="utf-8"))
    output = [
        "// Generated by tools/gen_symbols.py. See design/symbols.NOTICE.",
        '#include "krypton/ui/model/workspace_symbols.hpp"',
        "namespace kr {",
        "namespace {",
        "constexpr WorkspaceSymbol kSymbolCatalog[] = {",
    ]
    for item in symbols:
        value = json.dumps(item["value"], ensure_ascii=False)
        label = json.dumps(item["label"], ensure_ascii=False)
        output.append(f"    {{{value}, {label}, {'true' if item['icon'] else 'false'}}},")
    output.extend(["};", "}  // namespace", "const std::span<const WorkspaceSymbol> kWorkspaceSymbols{kSymbolCatalog};", "}  // namespace kr", ""])
    target = root / "modules/shell/src/commonMain/cpp/model/symbols.generated.cpp"
    target.write_text("\n".join(output), encoding="utf-8")
    print(f"Generated {len(symbols)} searchable symbols")


if __name__ == "__main__":
    main()
